    },
    {
      "name": "Finsupp.lsum_apply",
      "type": " {α : Type u_1} {M : Type u_2} {N : Type u_3} {R : Type u_4} {R₂ : Type u_5} (S : Type u_6) [Semiring R] [Semiring R₂] [Semiring S] [AddCommMonoid M] [Module R M] [AddCommMonoid N] [Module R₂ N] {σ : R →+* R₂} [Module S N] [SMulCommClass R₂ S N] (f : α → M →ₛₗ[σ] N) (l : α →₀ M) : ((Finsupp.lsum S) f) l = l.sum fun b => ⇑(f b)",
      "module": "Mathlib.LinearAlgebra.Finsupp.LSum"
    },
    {
      "name": "Finsupp.coe_lsum",
      "type": " {α : Type u_1} {M : Type u_2} {N : Type u_3} {R : Type u_4} {R₂ : Type u_5} (S : Type u_6) [Semiring R] [Semiring R₂] [Semiring S] [AddCommMonoid M] [Module R M] [AddCommMonoid N] [Module R₂ N] {σ : R →+* R₂} [Module S N] [SMulCommClass R₂ S N] (f : α → M →ₛₗ[σ] N) : ⇑((Finsupp.lsum S) f) = fun d => d.sum fun i => ⇑(f i)",
      "module": "Mathlib.LinearAlgebra.Finsupp.LSum"
    },
    {
      "name": "Finsupp.lsum_symm_apply",
      "type": " {α : Type u_1} {M : Type u_2} {N : Type u_3} {R : Type u_4} {R₂ : Type u_5} (S : Type u_6) [Semiring R] [Semiring R₂] [Semiring S] [AddCommMonoid M] [Module R M] [AddCommMonoid N] [Module R₂ N] {σ : R →+* R₂} [Module S N] [SMulCommClass R₂ S N] (f : (α →₀ M) →ₛₗ[σ] N) (x : α) : (Finsupp.lsum S).symm f x = f ∘ₛₗ Finsupp.lsingle x",
      "module": "Mathlib.LinearAlgebra.Finsupp.LSum"
    },
    {
      "name": "Submodule.range_lsum_smul",
      "type": " {R : Type u_1} {M : Type u_2} {N : Type u_3} {σ : Type u_4} [CommSemiring R] [AddCommMonoid M] [AddCommMonoid N] [Module R M] [Module R N] (φ : M →ₗ[R] N) (f : σ → R) : ((Finsupp.lsum R) fun x => f x • φ).range = Set.range f • φ.range",
