    },
    {
      "name": "Submodule.smul_top_eq_range_lsum",
      "type": " {R : Type u_1} {M : Type u_2} [CommSemiring R] [AddCommMonoid M] [Module R M] (s : Set R) : s • ⊤ = ((Finsupp.lsum R) fun i => ↑i • LinearMap.id).range",
      "module": "Mathlib.LinearAlgebra.Finsupp.Span"
    },
