      "name": "Submodule.image_smul_top_eq_range_lsum",
      "type": " {R : Type u_1} {M : Type u_2} {σ : Type u_4} [CommSemiring R] [AddCommMonoid M] [Module R M] (s : Set σ) (f : σ → R) : f '' s • ⊤ = ((Finsupp.lsum R) fun i => f ↑i • LinearMap.id).range",
      "module": "Mathlib.LinearAlgebra.Finsupp.Span"
    },
    {
      "name": "Submodule.set_smul_eq_map",
      "type": " {R : Type u_2} {M : Type u_3} [Semiring R] [AddCommMonoid M] [Module R M] (sR : Set R) (N : Submodule R M) [SMulCommClass R R ↥N] : sR • N = Submodule.map (N.subtype ∘ₗ (Finsupp.lsum R) (DistribSMul.toLinearMap R ↥N)) (Finsupp.supported (↥N) R sR)",
      "module": "Mathlib.Algebra.Module.Submodule.Finsupp"
    },
    {
      "name": "TensorProduct.sum_tmul_basis_left_injective",
      "type": " {R : Type u_1} {M : Type u_3} {N : Type u_4} {ι : Type u_5} [CommSemiring R] [AddCommMonoid M] [Module R M] [AddCommMonoid N] [Module R N] (ℬ : Module.Basis ι R M) : Function.Injective ⇑((Finsupp.lsum R) fun i => (TensorProduct.mk R M N) (ℬ i))",
      "module": "Mathlib.LinearAlgebra.TensorProduct.Basis"
    },
    {
      "name": "TensorProduct.equivFinsuppOfBasisLeft_symm",
      "type": " {R : Type u_1} {M : Type u_3} {N : Type u_4} {ι : Type u_5} [CommSemiring R] [AddCommMonoid M] [Module R M] [AddCommMonoid N] [Module R N] [DecidableEq ι] (ℬ : Module.Basis ι R M) : ↑(TensorProduct.equivFinsuppOfBasisLeft ℬ).symm = (Finsupp.lsum R) fun i => (TensorProduct.mk R M N) (ℬ i)",
      "module": "Mathlib.LinearAlgebra.TensorProduct.Basis"
    }
  ]
